=== schemas.ts ===
import { z } from 'zod'

/**
 * 成片还原 · 数据契约。
 *
 * 与 shotlist（正向：剧本→分镜）的关系：**数据流反过来，下游共用**。
 * shotlist 是「剧本 → 镜头对象」，reverse 是「成片 → 镜头对象」。
 * 镜头一旦落成结构化对象，下游（渲染器/导出/模具聚合）就同一套逻辑。
 *
 * 但字段不同：AI 短剧要的是**双提示词 + 首帧图**，真人线要的是景别/运镜/时长
 * 给剧组排拍摄计划。故各自独立 schema，不硬套。
 */

// ============ 逐镜分析（AI 产出）============

/** 景别 · 封闭枚举（与 shotlist 同一套词，保证两条线术语一致） */
export const SHOT_SIZES = [
  '大远景', '远景', '全景', '中景', '近景', '特写', '大特写', '空镜',
] as const
export type ShotSize = (typeof SHOT_SIZES)[number]

/** 运镜 · 封闭枚举 */
export const CAMERA_MOVES = [
  '固定', '推', '拉', '摇', '移', '跟', '升', '降', '手持', '环绕',
] as const
export type CameraMove = (typeof CAMERA_MOVES)[number]

/**
 * 单镜分析结果（LLM 看首帧图 + 台词 + 时长后产出）。
 *
 * ⚠️ `imagePrompt` 与 `videoPrompt` 的分工是硬约束，不是风格偏好：
 *  - imagePrompt 决定**长什么样**（主体/外观/构图/景别/光线/画风）→ 喂文生图
 *  - videoPrompt 只管**怎么动**（动作/运镜/幅度/节奏）→ 喂图生视频，吃上面那张图
 * videoPrompt **绝不重复描述长相**——长相已被首帧图锁死，重复描述反而让模型漂移。
 * 这是 AI 短剧实操共识（查证所得），不是我的偏好。
 */
export const ShotAnalysisSchema = z.object({
  shotSize: z.enum(SHOT_SIZES),
  camera: z.enum(CAMERA_MOVES),
  /** 画面里有什么（主体 + 环境 + 关键道具） */
  subject: z.string().min(1),
  /** 这一镜发生了什么动作 */
  action: z.string().min(1),
  /** 光线氛围（出图的关键输入） */
  lighting: z.string().default(''),
  /** 情绪/氛围基调 */
  mood: z.string().default(''),
  /** 画风特征词（聚合成 B 层模具的原料） */
  styleTags: z.array(z.string()).default([]),
})
export type ShotAnalysis = z.infer<typeof ShotAnalysisSchema>

/** LLM 单镜输出：分析 + 两条提示词 */
export const ShotReverseSchema = z.object({
  analysis: ShotAnalysisSchema,
  imagePrompt: z.string().min(1),
  videoPrompt: z.string().min(1),
})
export type ShotReverse = z.infer<typeof ShotReverseSchema>

// ============ 台词（从 ASR 按镜头区间切）============

export const ShotDialogueSchema = z.object({
  /** ASR 行的时间戳（秒），用于回溯定位 */
  atSec: z.number(),
  text: z.string().min(1),
})
export type ShotDialogue = z.infer<typeof ShotDialogueSchema>

// ============ B 层视觉模具（对 A 聚合，几乎免费）============

/**
 * 视觉模具 = 「这片子怎么做出来的」的可复用结论。
 *
 * 大部分字段是**纯统计**（镜长分布/景别分布/切点节奏），不用调 AI；
 * 只有 `styleSummary` / `lightingSummary` 需要一次便宜的 AI 归纳。
 * 这是 B 层「几乎免费」的原因，也是它能白送当卖点的原因。
 *
 * 这一层最难被模型厂商吃掉——他们做生成，不做「你这片子的套路是什么」。
 */
export interface VisualMold {
  /** 画风词（从各镜 styleTags 聚合出高频项 + AI 归纳一句） */
  styleTags: { tag: string; count: number }[]
  styleSummary: string
  /** 打光套路归纳 */
  lightingSummary: string
  /** 景别分布（哪种景别占多少） */
  shotSizeDist: { size: string; count: number; pct: number }[]
  /** 运镜分布 */
  cameraDist: { move: string; count: number; pct: number }[]
  /** 节奏 */
  pace: {
    shotCount: number
    totalSec: number
    avgSec: number
    medianSec: number
    minSec: number
    maxSec: number
    /** 超过 AI 单次生成上限的镜头数 */
    overLongCount: number
    /** 前 3 秒内的切点数——钩子节奏的硬指标 */
    cutsInFirst3Sec: number
    /** 前 10 秒内的切点数 */
    cutsInFirst10Sec: number
  }
}

// ============ 进度快照（前端轮询读）============

/**
 * 检测阶段进度（免费段）。
 * 检测本身极快（87s 片 <1s），慢的是下载 + 抽帧 + ASR，故按这三步报。
 */
export interface DetectProgress {
  phase: 'downloading' | 'detecting' | 'framing' | 'transcribing'
  /** framing 阶段的已抽帧数 / 总帧数；其余阶段为 0 */
  framesDone: number
  framesTotal: number
}

/** 分析阶段进度（收费段）· 已分析镜头数 */
export interface AnalyzeProgress {
  shotsDone: number
  shotsTotal: number
}

// ============ 任务状态机 ============

/**
 * reverse 任务状态。
 *
 * `detected` 是**免费停站**，且这个停站是**计价所必需**的，不是抄来的设计：
 * 计价单位是镜头数，而镜头数要检测完才知道——不检测完根本报不出价。
 * 顺带它也让用户在花钱前先确认「切得准不准」（可调阈值重跑，重跑免费）。
 */
export const REVERSE_STATUSES = [
  'pending', 'detecting', 'detected', 'analyzing', 'done', 'failed',
] as const
export type ReverseStatus = (typeof REVERSE_STATUSES)[number]

/** 活跃态（前端据此决定是否继续轮询） */
export const REVERSE_ACTIVE_STATUSES: readonly ReverseStatus[] = Object.freeze([
  'pending', 'detecting', 'detected', 'analyzing',
])

/**
 * 卡死判定态 · **不含 detected**——那是等用户确认报价的硬 Gate，
 * updatedAt 冻结属正常，误标会吞掉免费阶段的全部产出（切点+首帧+ASR）。
 */
export const REVERSE_STUCK_STATUSES: readonly ReverseStatus[] = Object.freeze([
  'detecting', 'analyzing',
])

