import type { ShotAnalysis, VisualMold } from './schemas'
import type { ShotRange } from './cut-detect'
import { OVER_LONG_SHOT_SEC } from './cut-detect'

/**
 * B 层「视觉模具」聚合（纯函数 · 几乎免费）。
 *
 * 这一层是对 A 层（逐镜分析）的**统计聚合**——数据已经在库里，不用再调 AI。
 * 这就是 B 层能白送当卖点的原因，也是它和 A 的依赖关系：
 * **A 抽不准，B 的模具就是假的**。
 *
 * 为什么这层最值钱：它最难被模型厂商吃掉。他们做生成，不做「你这片子的套路是什么」。
 * 用户拿到的不是 300 条提示词（那是 A），而是「这片子怎么做出来的」——
 * 画风词、打光套路、景别分布、镜长节奏、钩子放在第几秒。
 *
 * 只有 styleSummary / lightingSummary 需要一次便宜的 AI 归纳，由调用方注入。
 */

function median(nums: number[]): number {
  if (nums.length === 0) return 0
  const s = [...nums].sort((a, b) => a - b)
  const mid = Math.floor(s.length / 2)
  return s.length % 2 === 0 ? round2((s[mid - 1] + s[mid]) / 2) : s[mid]
}

function round2(n: number): number {
  return Math.round(n * 100) / 100
}

/** 频次统计 → 降序数组（同频次按名称稳定排序，避免每次聚合顺序抖动） */
function countBy(values: string[]): { key: string; count: number }[] {
  const m = new Map<string, number>()
  for (const v of values) {
    const k = v.trim()
    if (!k) continue
    m.set(k, (m.get(k) ?? 0) + 1)
  }
  return [...m.entries()]
    .map(([key, count]) => ({ key, count }))
    .sort((a, b) => b.count - a.count || a.key.localeCompare(b.key))
}

function toDist(values: string[], total: number): { count: number; pct: number; key: string }[] {
  return countBy(values).map((x) => ({
    ...x,
    pct: total > 0 ? Math.round((x.count / total) * 100) : 0,
  }))
}

export interface BuildMoldInput {
  shots: ShotRange[]
  /** 逐镜分析结果（与 shots 同序；未分析的传 null） */
  analyses: (ShotAnalysis | null)[]
  durationSec: number
  /** AI 归纳的画风一句话（调用方注入；缺省给空串，不阻塞模具其余部分） */
  styleSummary?: string
  /** AI 归纳的打光套路（同上） */
  lightingSummary?: string
}

/**
 * 聚合视觉模具。
 *
 * `pace.cutsInFirst3Sec` 是**钩子节奏的硬指标**：AI 短剧和短视频一样，
 * 前 3 秒决定留存。切点密度告诉用户「这片子开头是靠快切抓人还是靠一个长镜头」。
 */
export function buildVisualMold(input: BuildMoldInput): VisualMold {
  const { shots, analyses, durationSec } = input
  const lens = shots.map((s) => s.lengthSec)
  const total = shots.length

  const known = analyses.filter((a): a is ShotAnalysis => a != null)

  const styleTags = countBy(known.flatMap((a) => a.styleTags))
    .map(({ key, count }) => ({ tag: key, count }))

  // 切点 = 每个镜头的起点（首镜 0 不算切点）
  const cuts = shots.slice(1).map((s) => s.startSec)

  return {
    styleTags,
    styleSummary: input.styleSummary ?? '',
    lightingSummary: input.lightingSummary ?? '',
    shotSizeDist: toDist(known.map((a) => a.shotSize), known.length)
      .map(({ key, count, pct }) => ({ size: key, count, pct })),
    cameraDist: toDist(known.map((a) => a.camera), known.length)
      .map(({ key, count, pct }) => ({ move: key, count, pct })),
    pace: {
      shotCount: total,
      totalSec: round2(durationSec),
      avgSec: total > 0 ? round2(lens.reduce((a, b) => a + b, 0) / total) : 0,
      medianSec: median(lens),
      minSec: total > 0 ? Math.min(...lens) : 0,
      maxSec: total > 0 ? Math.max(...lens) : 0,
      overLongCount: shots.filter((s) => s.lengthSec > OVER_LONG_SHOT_SEC).length,
      cutsInFirst3Sec: cuts.filter((c) => c <= 3).length,
      cutsInFirst10Sec: cuts.filter((c) => c <= 10).length,
    },
  }
}

/**
 * 模具 → 人读的报告（markdown）。
 *
 * 导出与前端面板共用。刻意不写成「AI 分析报告」那种腔调——
 * 用户要的是能照着做的参数，不是一篇观后感。
 */
export function moldToMarkdown(mold: VisualMold, title: string): string {
  const p = mold.pace
  const out: string[] = [`## 《${title}》视觉模具\n`]

  out.push('### 节奏\n')
  out.push(`- 总时长 ${p.totalSec}s · ${p.shotCount} 个镜头`)
  out.push(`- 平均镜长 ${p.avgSec}s · 中位 ${p.medianSec}s（最短 ${p.minSec}s / 最长 ${p.maxSec}s）`)
  out.push(`- 前 3 秒切 ${p.cutsInFirst3Sec} 次、前 10 秒切 ${p.cutsInFirst10Sec} 次 ← 开场钩子节奏`)
  if (p.overLongCount > 0) {
    out.push(
      `- ⚠️ ${p.overLongCount} 个镜头超过 ${OVER_LONG_SHOT_SEC}s（AI 单次生成上限），` +
        `原片这几处可能是多次生成拼接或用了多场景指令`,
    )
  }

  if (mold.styleTags.length > 0) {
    out.push('\n### 画风\n')
    out.push(mold.styleTags.slice(0, 15).map((t) => `${t.tag}(${t.count})`).join(' · '))
    if (mold.styleSummary) out.push(`\n${mold.styleSummary}`)
  }

  if (mold.lightingSummary) {
    out.push('\n### 打光\n')
    out.push(mold.lightingSummary)
  }

  if (mold.shotSizeDist.length > 0) {
    out.push('\n### 景别分布\n')
    out.push(mold.shotSizeDist.map((d) => `${d.size} ${d.count} 镜(${d.pct}%)`).join(' · '))
  }

  if (mold.cameraDist.length > 0) {
    out.push('\n### 运镜分布\n')
    out.push(mold.cameraDist.map((d) => `${d.move} ${d.count} 镜(${d.pct}%)`).join(' · '))
  }

  return out.join('\n') + '\n'
}

AND (${t.rawCostUsd} IS NULL OR ${t.rawCostUsd} >= 0)`,
  ),
}))

// ============ reverse_jobs / reverse_shots ============
// AI 短剧「成片还原」· 2026-08-23。生产线内容端第二条腿，取代原「剧本转提示词」占位。
//
// 方向是**反向**：下载一条爆款 AI 短剧 → 上传 → 还原出整套生产文档。
// 与 shotlist（正向：剧本→分镜）数据流相反，但镜头落成结构化对象后下游共用。
//
// 两段式，中间一个免费停站：
//   detecting  切点检测 + 逐镜抽首帧 + ASR —— **免费**
//   detected   用户确认切得准不准（可调阈值重跑）+ 看到报价 —— 免费停站
//   analyzing  逐镜出双提示词 —— **收费**（reverse-shot 2 灵石/镜）
//
// ⚠️ detected 这个停站是**计价所必需**的，不是抄 shotlist 的设计：
// 计价单位是镜头数，而镜头数要检测完才知道——不检测完根本报不出价。
//
// 核心事实：AI 短剧里一个切点 ≈ 一次生成。故 scdet 读到的剪辑点就是生产单元边界，
// 还原出的清单接近 1:1（已知例外见 lib/reverse/cut-detect.ts 的 Seedance 说明）。
//
// ⚠️ 迁移走手写 SQL（drizzle/manual/2026-08-23-reverse.sql）+ psql，绝不 db:push
//    —— 本仓 drizzle/meta/ 从未提交，db:generate 会产出全表伪迁移。

export const reverseJobs = pgTable('reverse_jobs', {
  id: uuid('id').primaryKey().defaultRandom(),
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  title: text('title').notNull(),
  /** 上传的成片 R2 key */
  sourceR2Key: text('source_r2_key').notNull(),
  durationSec: real('duration_sec'),
  /** scdet 阈值 · 存下来允许换阈值重跑（重跑免费，检测本身几乎零成本） */
  scdetThreshold: integer('scdet_threshold').notNull().default(10),
  /** pending|detecting|detected|analyzing|done|failed（见 lib/reverse/schemas.ts） */
  status: text('status').$type<ReverseStatus>().notNull().default('pending'),
  /** 检测出的镜头数 · 计价单位（detected 后才有值） */
  shotCount: integer('shot_count'),
  /** 整片 ASR 转写（`[m:ss] 台词` 行格式 · 复用 lib/pullfilm/asr.ts 契约） */
  asrTranscript: text('asr_transcript'),
  /** B 层视觉模具（对 A 聚合 · 不单独收费） */
  mold: jsonb('mold').$type<VisualMold>(),
  detectProgress: jsonb('detect_progress').$type<DetectProgress>(),
  analyzeProgress: jsonb('analyze_progress').$type<AnalyzeProgress>(),
  errorMessage: text('error_message'),
  createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  completedAt: timestamp('completed_at', { withTimezone: true }),
}, (t) => ({
  userCreatedIdx: index('idx_reverse_jobs_user_created').on(t.userId, t.createdAt),
  statusIdx: index('idx_reverse_jobs_status').on(t.status),
}))

export const reverseShots = pgTable('reverse_shots', {
  id: uuid('id').primaryKey().defaultRandom(),
  jobId: uuid('job_id').notNull().references(() => reverseJobs.id, { onDelete: 'cascade' }),
  shotNo: integer('shot_no').notNull(),
  startSec: real('start_sec').notNull(),
  endSec: real('end_sec').notNull(),
  lengthSec: real('length_sec').notNull(),
  /** 首帧图 R2 key（取 startSec+0.15s 避开转场混合帧）· AI 短剧最硬的产物 */
  frameR2Key: text('frame_r2_key'),
  /** 超过 AI 单次生成上限（10s）· 前端标红 + 建议拆分 */
  overLong: boolean('over_long').notNull().default(false),
  /** 建议拆分份数（overLong 时按 8s/份）· null=不超长 */
  suggestSplitInto: integer('suggest_split_into'),
  /** 逐镜分析（景别/运镜/主体/画面/光线/情绪/画风词） */
  analysis: jsonb('analysis').$type<ShotAnalysis>(),
  /** 首帧图提示词 —— 决定「长什么样」，喂文生图 */
  imagePrompt: text('image_prompt'),
  /** 视频提示词 —— 只管「怎么动」，喂图生视频（吃 frameR2Key 那张图）
   *  绝不重复描述长相：长相已被首帧锁死，重复描述会让模型漂移 */
  videoPrompt: text('video_prompt'),
  /** 本镜台词（从 ASR 按时间区间切） */
  dialogue: jsonb('dialogue').$type<ShotDialogue[]>(),
  status: text('status').notNull().default('pending'), // pending|done|failed
  createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
}, (t) => ({
  jobShotUniq: uniqueIndex('uq_reverse_shots_job_shot').on(t.jobId, t.shotNo),
}))

import type { ModuleKey } from '@/components/ui/ModuleIcon'

export interface NavItem {
  /** 稳定标识（ModuleKey 或本地扩展键）· 用作 React key 与灰度判定 */
  key: ModuleKey | 'script-to-shots' | 'materials'
  href: string
  label: string
  /**
   * @deprecated 导航一律纯文字（owner 明确要求）。字段保留仅因 ModuleIcon 等
   * 品牌身份块仍在用；侧栏与移动抽屉都不再渲染它。
   */
  emoji: string
  /** false = 功能未上线 · 渲染为灰态 +「待上线」角标，不可点，不给死链 */
  available: boolean
  /**
   * 生产线的哪一端：writer=编剧端（找参考/写/质检）· content=内容端（拆分镜/还原）。
   * 分隔线位置由它判定，**不能靠 available 推导**——那等于假设内容端功能全没上线，
   * 一旦有内容端功能上线该假设就失效（见 navGroupsForScreenplayAccess 注释）。
   * 仅「生产线」组的条目需要这个字段。
   */
  side?: 'writer' | 'content'
}

export interface NavGroup {
  title: string
  items: NavItem[]
  /**
   * 组内分隔线插入位置（在第 N 项之后画一条淡线）。
   * 生产线用它区隔「编剧端已上线的几条」与「内容端待上线的两条」，
   * 不加子标题也能让人看出这是两个阶段。
   */
  dividerAfter?: number
}

/**
 * 聚超超工作台左侧导航 · 单一事实源（分组结构）。
 *
 * 分组定位（Owner 定稿 2026-08-23）：生产线 / 学习 / 交流。
 * 组内条目与顺序后续大概率还会调——**调整只改本文件的数组，渲染组件不动**。
 *
 * 「账号」不单独成组：底部固定区的 AccountMenuClient 已经是 /account 的入口，
 * 再在滚动区放一条是重复入口；且侧栏高度是硬约束（见 sidebar-nav.test.ts 的
 * 条目上限），多一组标题 + 一条目 = 多 85px，会把底部固定区挤出 13″ 视口。
 *
 * 生产线按**生产顺序**排，导航本身就是说明书：
 *   找参考(短剧转剧本) → 写(爆款仿写) → 质检(剧本审稿) ┊ 拆分镜(转脚本) → 出图(转提示词)
 * 前几条是编剧端、后两条是内容端，中间一条淡分隔线（dividerAfter）。
 * 内容端功能未建，用 `available:false` 占位标「待上线」而非隐藏——对工作室来说
 * 这是产品路线图，是卖点不是缺陷；规格到位后把 available 翻真 + 填 href 即可。
 *
 * 不在这里的东西及其去处：
 *  - 三类包（积分/资料/课程）→ 货架页 /pricing，底部余额条点「充值」进
