 */
export function navItemsForScreenplayAccess(allowed: boolean): NavItem[] {
  return navGroupsForScreenplayAccess(allowed).flatMap((g) => g.items)
}

import { NextResponse } from 'next/server'
import { auth } from '@/lib/auth'
import { db } from '@/lib/db'
import {
  pullfilmJobs, pullfilmScripts, imitateJobs, imitateEpisodes,
} from '@/lib/db/schema'
import { and, desc, eq, isNotNull, sql } from 'drizzle-orm'

/**
 * GET /api/shotlist/sources
 *
 * 列出可一键导入分镜的既有剧本 —— **生产线的接缝**。
 * 侧栏把生产线按顺序排（找参考→写→质检→拆分镜→出图）只是把顺序画出来；
 * 让上一站的产物能直接进下一站，那条线才真的通了（否则用户得先下载再上传）。
 *
 * 两个来源：
 *  - pullfilm（视频转剧本）：有单集稿的任务（episode_no 非空那些行）
 *  - imitate（仿写 Agent）：有正文的任务
 *
 * 只列本人的、且**真的有集可导**的（episodeCount>0）——列出来点进去发现是空的，
 * 比不列更糟。按创建时间倒序，各取 30 条（够用，重度用户再补分页）。
 */
export async function GET() {
  const session = await auth()
  const userId = (session?.user as { id?: string } | undefined)?.id
  if (!userId) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  // pullfilm：按 job 聚合单集稿数量。episode_no IS NULL 那行是「全剧汇总」，不计。
  const pullfilm = await db
    .select({
      id: pullfilmJobs.id,
      scriptName: pullfilmJobs.scriptName,
      createdAt: pullfilmJobs.createdAt,
      episodeCount: sql<number>`count(${pullfilmScripts.id})::int`,
    })
    .from(pullfilmJobs)
    .innerJoin(
      pullfilmScripts,
      and(eq(pullfilmScripts.jobId, pullfilmJobs.id), isNotNull(pullfilmScripts.episodeNo)),
    )
    .where(eq(pullfilmJobs.userId, userId))
    .groupBy(pullfilmJobs.id, pullfilmJobs.scriptName, pullfilmJobs.createdAt)
    .orderBy(desc(pullfilmJobs.createdAt))
    .limit(30)

  const imitate = await db
    .select({
      id: imitateJobs.id,
      scriptName: imitateJobs.scriptName,
      createdAt: imitateJobs.createdAt,
      episodeCount: sql<number>`count(${imitateEpisodes.id})::int`,
    })
    .from(imitateJobs)
    .innerJoin(
      imitateEpisodes,
      and(eq(imitateEpisodes.jobId, imitateJobs.id), isNotNull(imitateEpisodes.body)),
    )
    .where(eq(imitateJobs.userId, userId))
    .groupBy(imitateJobs.id, imitateJobs.scriptName, imitateJobs.createdAt)
    .orderBy(desc(imitateJobs.createdAt))
    .limit(30)

  return NextResponse.json({
    sources: [
      ...pullfilm.map((r) => ({ ...r, sourceKind: 'pullfilm' as const })),
      ...imitate.map((r) => ({ ...r, sourceKind: 'imitate' as const })),
    ]
      .filter((r) => r.episodeCount > 0)
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()),
  })
}
