import type { ShotlistSourceKind } from './schemas'

/**
 * init 的三条入口收口成一份「集号 → 正文」映射（纯函数部分）。
 *
 * 三条路：
 *  - upload：用户上传 / 粘贴 → `parseScript` 分集
 *  - pullfilm：从「视频转剧本」的成品导入
 *  - imitate：从「仿写 Agent」的成品导入
 *
 * 后两条是**生产线真正的接缝**：视频转剧本出的稿直接进转脚本，用户不用「下载再上传」。
 * 侧栏把生产线按顺序排（找参考→写→质检→拆分镜→出图）只是把顺序画出来；
 * 让上一站的产物能一键进下一站，才是那条线真的通了。
 */

export interface SourceEpisode {
  episodeNo: number
  scriptMd: string
}

/** 单集正文的最小长度（字符）· 太短的（空集/占位）不该进分镜，否则白扣一集的钱 */
export const MIN_EPISODE_CHARS = 80

export interface NormalizeSourceResult {
  episodes: SourceEpisode[]
  /** 因过短被剔除的集号（前端提示用 · 不静默丢弃） */
  skipped: number[]
}

/**
 * 规整来源集列表：按集号升序、去重（同集号留第一条）、剔除过短集。
 *
 * 为什么剔除过短集：pullfilm 的 degraded/failed 集会留占位文本，
 * imitate 也可能有空集。让它们进来 = 用户为一集空白付 5 灵石，
 * 且分镜阶段必然抛「未找到合法场景头」把整个任务打成 failed。
 * 在入口剔掉 + 明示跳了哪几集，比事后退款体验好得多。
 */
export function normalizeSourceEpisodes(rows: SourceEpisode[]): NormalizeSourceResult {
  const seen = new Set<number>()
  const episodes: SourceEpisode[] = []
  const skipped: number[] = []

  for (const r of [...rows].sort((a, b) => a.episodeNo - b.episodeNo)) {
    if (!Number.isInteger(r.episodeNo) || r.episodeNo < 1) continue
    if (seen.has(r.episodeNo)) continue
    seen.add(r.episodeNo)
    const md = (r.scriptMd ?? '').trim()
    if (md.length < MIN_EPISODE_CHARS) { skipped.push(r.episodeNo); continue }
    episodes.push({ episodeNo: r.episodeNo, scriptMd: md })
  }

  return { episodes, skipped }
}

/** 剧名兜底：来源没给名字时用文件名/默认值，不落空串（列表页会显示成空行） */
export function deriveScriptName(
  raw: string | null | undefined,
  fallbackFileName?: string | null,
): string {
  const trimmed = (raw ?? '').trim()
  if (trimmed) return trimmed.slice(0, 80)
  const fromFile = (fallbackFileName ?? '').replace(/\.(docx|txt|md)$/i, '').trim()
  if (fromFile) return `分镜-${fromFile}`.slice(0, 80)
  return '未命名分镜'
}

/** 入参里的 sourceKind 是否合法（前端可伪造，服务端必校验） */
export function isValidSourceKind(v: unknown): v is ShotlistSourceKind {
  return v === 'upload' || v === 'pullfilm' || v === 'imitate'
}

