// src/lib/inngest/functions/reverse-analyze.ts
import { inngest } from '../client'
import { db } from '@/lib/db'
import { reverseJobs, reverseShots } from '@/lib/db/schema'
import { eq, and, asc } from 'drizzle-orm'
import { getObjectBuffer } from '@/lib/r2'
import { runWithRetry } from '@/lib/generate/ai/run-with-retry'
import { visionChatFnWithFrame, chatForReverseText } from '@/lib/reverse/chat-adapter'
import {
  buildShotReversePrompt, ShotReverseOutSchema,
  buildMoldSummaryPrompt, MoldSummarySchema,
} from '@/lib/reverse/prompts'
import { buildVisualMold } from '@/lib/reverse/mold'
import { notifyReverseDone, reconcileReverseAnalyzeFailure } from '@/lib/reverse/stage-lifecycle'
import type { AnalyzeProgress, ShotAnalysis, ShotDialogue } from '@/lib/reverse/schemas'
import type { ShotRange } from '@/lib/reverse/cut-detect'

interface Payload { jobId: string }
interface StepCtx { run<T>(name: string, fn: () => Promise<T> | T): Promise<T> }

/** 累积画风词的取样上限：前 N 镜的画风词喂给后续镜，保证全片风格描述一致 */
const STYLE_SEED_SHOTS = 5
/** 喂给后续镜的高频画风词个数 */
const STYLE_SEED_TAGS = 6

/**
 * 收费段：逐镜还原双提示词 + 聚合视觉模具。
 *
 * 每镜一个 step.run：喂**首帧图**（内联 base64）+ 台词 + 时长 + 上一镜画面，
 * 出「分析 + imagePrompt + videoPrompt」。
 *
 * 两个刻意的设计：
 *  ① **画风词累积回喂**：前 5 镜分析出的高频画风词，注入后续镜的 prompt，
 *    避免同一部片子每镜风格描述漂移（模型逐镜独立看图时很容易这样）。
 *  ② **每镜心跳** touch updatedAt：cleanup cron 按「40min 无进展」判卡死，
 *    300 镜串行会很久，无心跳活任务必被误标 failed + 误退款。
 *
 * 计费不在本函数——由 `analyze/start` 路由扣费成功后才发事件触发。
 */
export async function reverseAnalyzeHandler(
  { event, step }: { event: { data: Payload }; step: StepCtx },
) {
  const { jobId } = event.data

  const ctx = await step.run('load', async () => {
    const [job] = await db.select().from(reverseJobs).where(eq(reverseJobs.id, jobId)).limit(1)
    if (!job) throw new Error(`reverse job ${jobId} not found`)
    if (!job.shotCount || job.shotCount < 1) throw new Error('shotCount missing（未完成检测）')
    const shots = await db
      .select()
      .from(reverseShots)
      .where(eq(reverseShots.jobId, jobId))
      .orderBy(asc(reverseShots.shotNo))
    if (shots.length === 0) throw new Error('no shots to analyze')
    return { title: job.title, durationSec: job.durationSec ?? 0, shots }
  })

  await step.run('mark-analyzing', async () => {
    await db.update(reverseJobs).set({
      status: 'analyzing',
      errorMessage: null,
      analyzeProgress: { shotsDone: 0, shotsTotal: ctx.shots.length } satisfies AnalyzeProgress,
      updatedAt: new Date(),
    }).where(eq(reverseJobs.id, jobId))
  })

  // 累积状态在 step.run 外（replay 安全：step 结果走缓存，累积过程可重演）
  const styleTagCounts = new Map<string, number>()
  let prevAction: string | null = null

  for (let i = 0; i < ctx.shots.length; i++) {
    const shot = ctx.shots[i]
    const seedTags = topTags(styleTagCounts, STYLE_SEED_TAGS)
    const prev = prevAction

    const analyzed = await step.run(`analyze-shot-${shot.shotNo}`, async () => {
      // 首帧图：内联 base64（对 Gemini 与 Anthropic 兼容中转都成立；~24KB 可忽略）
      let frame: Buffer | null = null
      if (shot.frameR2Key) {
        try {
          frame = await getObjectBuffer(shot.frameR2Key)
        } catch (err) {
          console.warn(
            `[reverse-analyze] 取首帧失败（降级为无图分析）· shot=${shot.shotNo} · ${
              err instanceof Error ? err.message : err
            }`,
          )
        }
      }

      const prompt = buildShotReversePrompt({
        shotNo: shot.shotNo,
        totalShots: ctx.shots.length,
        lengthSec: shot.lengthSec,
        dialogue: (shot.dialogue ?? []) as ShotDialogue[],
        overLong: shot.overLong,
        suggestSplitInto: shot.suggestSplitInto,
        prevAction: prev,
        knownStyleTags: seedTags,
      })

      const result = await runWithRetry({
        chat: visionChatFnWithFrame(frame),
        model: 'gemini-3-flash-preview',
        messages: [{ role: 'user', content: prompt }],
        schema: ShotReverseOutSchema,
        maxRetries: 3,
        timeoutMs: 90_000,
        maxTokens: 4000,
      })

      const { analysis, imagePrompt, videoPrompt } = result.shot

      await db.update(reverseShots).set({
        analysis, imagePrompt, videoPrompt, status: 'done', updatedAt: new Date(),
      }).where(and(eq(reverseShots.jobId, jobId), eq(reverseShots.shotNo, shot.shotNo)))

      // 心跳 + 进度（见函数头：无心跳长任务必被 cron 误杀）
      await db.update(reverseJobs).set({
        analyzeProgress: {
          shotsDone: shot.shotNo, shotsTotal: ctx.shots.length,
        } satisfies AnalyzeProgress,
        updatedAt: new Date(),
      }).where(eq(reverseJobs.id, jobId))

      return { analysis, action: analysis.action }
    })

    // 累积画风词（只取前 STYLE_SEED_SHOTS 镜做种子，之后不再变，保证 prompt 稳定）
    if (i < STYLE_SEED_SHOTS) {
      for (const t of analyzed.analysis.styleTags) {
        styleTagCounts.set(t, (styleTagCounts.get(t) ?? 0) + 1)
      }
    }
    prevAction = analyzed.action
  }

  // B 层模具：纯统计 + 一次便宜的 AI 归纳（不喂图）
  await step.run('build-mold', async () => {
    const rows = await db
      .select()
      .from(reverseShots)
      .where(eq(reverseShots.jobId, jobId))
      .orderBy(asc(reverseShots.shotNo))

    const shotRanges: ShotRange[] = rows.map((r) => ({
      shotNo: r.shotNo,
      startSec: r.startSec,
      endSec: r.endSec,
      lengthSec: r.lengthSec,
      overLong: r.overLong,
      suggestSplitInto: r.suggestSplitInto,
    }))
    const analyses = rows.map((r) => (r.analysis ?? null) as ShotAnalysis | null)

    // 先出纯统计部分（不依赖 AI · AI 归纳失败也要有模具）
    const base = buildVisualMold({ shots: shotRanges, analyses, durationSec: ctx.durationSec })

    let styleSummary = ''
    let lightingSummary = ''
    try {
      const summary = await runWithRetry({
        chat: chatForReverseText,
        model: 'gemini-3-flash-preview',
        messages: [{
          role: 'user',
          content: buildMoldSummaryPrompt({
            title: ctx.title,
            styleTags: base.styleTags,
            lightingSamples: analyses.filter(Boolean).map((a) => a!.lighting).filter(Boolean),
            shotCount: shotRanges.length,
          }),
        }],
        schema: MoldSummarySchema,
        maxRetries: 2,
        timeoutMs: 60_000,
        maxTokens: 1500,
      })
      styleSummary = summary.styleSummary
      lightingSummary = summary.lightingSummary
    } catch (err) {
      // 归纳失败不阻塞：统计部分（镜长/景别/运镜/节奏）本身就是模具主体
      console.warn(
        `[reverse-analyze] 模具归纳失败（保留统计部分）· jobId=${jobId} · ${
          err instanceof Error ? err.message : err
        }`,
      )
    }

    await db.update(reverseJobs).set({
      mold: { ...base, styleSummary, lightingSummary },
      status: 'done',
      completedAt: new Date(),
      updatedAt: new Date(),
    }).where(eq(reverseJobs.id, jobId))
  })

  await step.run('notify-done', () => notifyReverseDone(jobId))
}

/** 取频次最高的 N 个画风词（同频次按名称稳定排序，避免 prompt 每次抖动） */
function topTags(counts: Map<string, number>, n: number): string[] {
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, n)
    .map(([tag]) => tag)
}

export const reverseAnalyze = inngest.createFunction(
  {
    id: 'reverse-analyze',
    retries: 2,
    // retries 耗尽 → CAS 标 failed + 按未完成镜数退款 + 通知
    // （幂等键与 cleanup cron 相同，双层防双退）
    onFailure: async (
      { event, step }: { event: { data: { event: { data?: Payload } } }; step: StepCtx },
    ) => {
      const { jobId } = event.data.event.data ?? ({} as Payload)
      if (!jobId) return
      await step.run('reconcile-failure', () => reconcileReverseAnalyzeFailure(jobId))
    },
    triggers: [{ event: 'reverse/analyze.requested' }],
  },
  reverseAnalyzeHandler as never,
)

import type { Asset, Shot } from './schemas'
import { ASSET_KIND_LABEL } from './schemas'
import { normalizeAssetKey } from './assets-merge'

/**
 * 把镜头的 `subjects`（assetKey 指针）展开成完整外观描述（纯函数）。
 *
 * 这是「一致性」真正落地的地方，也是本模块存在的理由：
 *   镜头里存 `subjects: ['林小满', '总裁办公室']`
 *   → 展开成「林小满（25岁女，齐肩黑发，米白针织衫+牛仔裤）在总裁办公室（落地窗+黑胡桃木桌）」
 *
 * 为什么不在生成镜头时就把描述写进去：那样同一角色在 30 个镜头里会有 30 份
 * 各自漂移的描述（LLM 每次措辞都不同），用户改一次也只能改一条。
 * 指针 + 展开 = 改一次资产表，全剧 30 个镜头同步变。
 *
 * 角色会自动带上其默认服装（`wardrobeKey` 指向的 wardrobe 资产）——
 * 「同一身衣服」是用户明确点出的痛点，靠 character→wardrobe 这一跳解决。
 */

/** 资产查找表：归一 key → 资产（跨 kind 建索引，subjects 不带 kind 前缀） */
export function buildAssetIndex(assets: Asset[]): Map<string, Asset> {
  const m = new Map<string, Asset>()
  for (const a of assets) {
    const nk = normalizeAssetKey(a.key)
    // 先到先得：同名跨 kind 时优先 character（subjects 里同名多指角色）
    if (!m.has(nk) || a.kind === 'character') m.set(nk, a)
  }
  return m
}

/**
 * 单条资产 → 一行描述（角色自动拼上服装）。
 *
 * `overrideWardrobe` 用于**本镜头换装**：剧本里同一角色会换衣服（办公室针织衫 →
 * 医院灰卫衣），若一律拼默认那套，医院那场的描述就和画面对不上——这正是
 * 「同一身衣服」承诺的反面。故镜头可在 subjects 里显式带上本场的 wardrobe key，
 * resolveShot 识别到就用它覆盖默认（2026-08-23 活体真跑发现的缺口）。
 */
export function describeAsset(
  asset: Asset,
  index: Map<string, Asset>,
  overrideWardrobe?: Asset | null,
): string {
  const parts = [asset.desc]
  if (asset.kind === 'character') {
    const w = overrideWardrobe
      ?? (asset.wardrobeKey ? index.get(normalizeAssetKey(asset.wardrobeKey)) : undefined)
    if (w) parts.push(w.desc)
  }
  return `${asset.name}（${parts.filter(Boolean).join('；')}）`
}

