  unresolved: string[]
}

/**
 * 展开单个镜头的 subjects。
 *
 * 若本镜头 subjects 里同时出现了角色和某套 wardrobe，视为**本镜换装**：
 * 用那套覆盖角色的默认服装，且那条 wardrobe 不再单独出一行
