/**
 * 分镜导出（纯函数 · 三种格式）。
 *
 * 三种不是为了凑数，各有真实用途：
 *  - **csv**：给制片。一行一镜头，直接进 Excel 排拍摄计划（按场归堆、算总时长、
 *    标已拍未拍）。这是工作室真实工作流里最常用的一份。
 *  - **md**：给导演/摄影看的表格版，带资产表附录（现场核对「这个角色该穿什么」）。
 *  - **txt**：给不方便看表格的场合（打印、微信发），逐镜纵向排列。
 *
 * subjects 在导出时**展开成完整描述**（不是导出 assetKey）——拿着导出文件的人
 * 手上没有资产表，看到「林小满」三个字不知道该化什么妆、穿什么衣服。
 */

/** 一集的分镜数据 */
export interface ExportEpisode {
  episodeNo: number
  shots: Shot[]
}

export interface ExportInput {
  scriptName: string
  assets: Asset[]
  episodes: ExportEpisode[]
}

/** 台词一行的可读形式（os/vo 标出来，配音要按这个分） */
function dialogueText(shot: Shot): string {
  return shot.dialogue
    .map((d) => {
      const tag = d.kind === 'os' ? ' os' : d.kind === 'vo' ? ' vo' : ''
      const emo = d.emotion ? `（${d.emotion}）` : ''
      return `${d.who}${tag}${emo}：${d.line}`
    })
    .join(' / ')
}

import { NextResponse } from 'next/server'
import { auth } from '@/lib/auth'
import { db } from '@/lib/db'
import { reverseJobs, reverseShots } from '@/lib/db/schema'
import { and, eq, sql } from 'drizzle-orm'
import { inngest } from '@/lib/inngest/client'
import {
  consumeByFeature, InsufficientCreditsError, DebitInProgressError,
} from '@/lib/billing/consume-by-feature'
import { refundReverseCredits } from '@/lib/billing/refund-on-failure'
import { REVERSE_REFUND_PER_SHOT } from '@/lib/billing/credit-prices'

/**
 * POST /api/reverse/jobs/[id]/analyze/start
 *
 * **收费落点**：按未完成镜数扣费 + 发事件逐镜还原。
 *
 * 顺序（照 shotlist/imitate 的顺序铁律）：
 *  1. 状态守卫（detected 首次 / failed 重试）
 *  2. 算未完成镜数（重试时只算还没出的，已付过的不重扣）
 *  3. 扣费（幂等键 `reverse-analyze-<jobId>`）
 *  4. 置 analyzing + 发事件；**发事件失败则退款 + 回滚状态**
 */
export async function POST(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const session = await auth()
  const userId = (session?.user as { id?: string } | undefined)?.id
  if (!userId) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  const { id: jobId } = await params

  const [job] = await db.select().from(reverseJobs)
    .where(and(eq(reverseJobs.id, jobId), eq(reverseJobs.userId, userId)))
    .limit(1)
  if (!job) return NextResponse.json({ error: 'not_found' }, { status: 404 })

  // 允许从 detected 起（首次），或从 failed 重试（已扣过的靠幂等键不重扣）
  if (job.status !== 'detected' && job.status !== 'failed') {
    return NextResponse.json({ error: '任务状态不符，无法开始还原' }, { status: 409 })
  }
  if (!job.shotCount || job.shotCount < 1) {
    return NextResponse.json({ error: '尚未完成镜头检测' }, { status: 400 })
  }

  const [{ doneCount }] = await db
    .select({ doneCount: sql<number>`count(*)::int` })
    .from(reverseShots)
    .where(and(eq(reverseShots.jobId, jobId), eq(reverseShots.status, 'done')))
  const shotCount = Math.max(0, job.shotCount - (doneCount ?? 0))
  if (shotCount === 0) {
    return NextResponse.json({ error: '全部镜头已还原' }, { status: 400 })
  }

  const idemKey = `reverse-analyze-${jobId}`
  try {
    await consumeByFeature({
      userId,
      kind: 'reverse-shot',
      shotCount,
      refType: 'reverse_job',
      refId: jobId,
      idempotencyKey: idemKey,
      note: `成片还原 ${shotCount} 镜双提示词`,
    })
  } catch (err) {
    if (err instanceof InsufficientCreditsError) {
      return NextResponse.json(
        { error: 'insufficient-credits', required: err.required, available: err.available },
        { status: 402 },
      )
    }
    if (err instanceof DebitInProgressError) {
      return NextResponse.json({ error: '处理中，请勿重复提交' }, { status: 409 })
    }
    throw err
  }

  const prevStatus = job.status
  await db.update(reverseJobs)
    .set({ status: 'analyzing', errorMessage: null, updatedAt: new Date() })
    .where(eq(reverseJobs.id, jobId))

  try {
    await inngest.send({ name: 'reverse/analyze.requested', data: { jobId } })
  } catch (err) {
    await refundReverseCredits(
      userId,
      shotCount * REVERSE_REFUND_PER_SHOT,
      `reverse-analyze-refund-${jobId}`,
      '还原启动失败全额退款',
    )
    await db.update(reverseJobs)
      .set({ status: prevStatus, updatedAt: new Date() })
      .where(eq(reverseJobs.id, jobId))
    console.error(
      `[POST /api/reverse/jobs/${jobId}/analyze/start] inngest.send 失败`,
      err instanceof Error ? err.message : err,
    )
    return NextResponse.json({ error: '启动失败，已退款，请重试' }, { status: 500 })
  }

  return NextResponse.json({ ok: true, shotCount })
}

