/**
 * Server-selected navigation; rollout membership never enters client config.
 * 灰度项插在编剧端末尾（剧本审稿之后、分隔线之前），与灰度前的相对顺序一致。
 */
export function navGroupsForScreenplayAccess(allowed: boolean): NavGroup[] {
  const production = [...PRODUCTION_ITEMS]
  // 编剧端 = 分隔线之前那几条。
  // ⚠️ 这里**不能**用 `filter(i => i.available).length` 推导：那等价于假设
  // 「所有内容端功能都还没上线」。2026-08-23「剧本转脚本」上线后该假设即失效，
  // 分隔线会跑到它之后，把它错划进编剧端。故按 side 显式判定。
  const writerSideCount = PRODUCTION_ITEMS.filter((i) => i.side === 'writer').length
  if (allowed) {
    production.splice(writerSideCount, 0, SCREENPLAY_NAV_ITEM)
  }
  return [
    {
      title: '生产线',
      items: production,
      dividerAfter: allowed ? writerSideCount + 1 : writerSideCount,
    },
    { title: '学习', items: LEARNING_ITEMS },
    { title: '交流', items: COMMUNITY_ITEMS },
  ]
}

